head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > ondatadrop]<br/>Drag 된 데이터가 다른 GridView 에 Drop 되었을때 발생합니다.",
    "validation" : [
        "데이터 Drag&Drop 과 관련된 이벤트는 ondatadragstart > ondatadragover > [dragStartFunction] > [ondatadrop|dragEndFunction] 순서로 발생합니다.",
        "dragStartFunction 속성의 사용자 함수는 Drag 가 시작된 GridView 에 정의된 경우 데이터가 Drop 될 때 호출됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제 (2개 그리드 + 2개 dataList)
    if (typeof dlt_bind1 !== 'undefined') {
        $p.data.remove("dlt_bind1");
    }
    if (typeof dlt_bind2 !== 'undefined') {
        $p.data.remove("dlt_bind2");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof target2 !== 'undefined') {
        target2.remove();
    }
    // 이전에 만든 flex wrapper 도 제거 (Target 재생성 시 중복 누적 방지)
    if (scwin.gridFlexWrap && scwin.gridFlexWrap.parentNode) {
        scwin.gridFlexWrap.parentNode.removeChild(scwin.gridFlexWrap);
    }

    // 안내 라벨 (가장 먼저 생성)
    //  - Drag&Drop 관련 이벤트의 전체 발생 순서를 한 곳에서 확인
    $c.gcm.createLabel('label="[전제] 왼쪽=target1(소스, dragStartFunction 정의)/오른쪽=target2(Drop 대상). 양쪽 dataDragDropOther=true.\n[절차] target1 의 Row 를 Drag 해 target2 에 Drop.\n[확인] 결과창에 ▶ 표시가 ondatadragstart > ondatadragover > dragStartFunction > ondatadrop 순서로 출력됩니다."', '', 'label1');

    // 좌우 배치용 flex wrapper 와 좌/우 셀(원시 DOM div) 생성
    //  - 기본 케이스가 .tc_group_basic(원시 DOM)을 dynamicCreate parent 로 쓰므로 좌/우 셀도 원시 DOM div 로 생성
    //  - 각 셀을 createBasicGridView 의 cParent 로 넘겨 두 그리드를 양옆으로 배치
    let grpBasic = document.querySelector('.tc_group_basic');
    scwin.gridFlexWrap = document.createElement('div');
    scwin.gridFlexWrap.style.cssText = 'display:flex; gap:20px; align-items:flex-start;';
    let cellLeft = document.createElement('div');
    let cellRight = document.createElement('div');
    scwin.gridFlexWrap.appendChild(cellLeft);
    scwin.gridFlexWrap.appendChild(cellRight);
    grpBasic.appendChild(scwin.gridFlexWrap);

    // 양 그리드에 dataDragDropOther=true (교차 그리드 Drag&Drop 허용)
    //  - dataDragDrop/dataDragDropSelf/dataDragDropOther/dataDragDropCell 중 하나 이상 true 여야 이벤트 발생
    //  - target1(소스) 에 dragStartFunction 속성으로 사용자 함수명 문자열 지정 -> Drop 시 호출 (ondatadrop 보다 먼저)
    let properties1 = {
        dataList: "data:dlt_bind1",
        dataDragDropOther: "true",
        dragStartFunction: "scwin.target1_dragStartFunc"
    };
    let properties2 = {
        dataList: "data:dlt_bind2",
        dataDragDropOther: "true"
    };

    let cList1 = $c.gcm.createCList(properties1);
    let cList2 = $c.gcm.createCList(properties2);

    // ondatadragover 발생 횟수 카운터 초기화 (ondatadragover 는 Drag-over 동안 연속 발생 -> 3회까지만 출력)
    scwin.overCnt = 0;

    // 이벤트 핸들러 부착 (전체 체인이 한 번에 보이도록)
    //  - target1(소스) : ondatadragstart (+ dragStartFunction 은 속성으로 별도 지정)
    //  - target2(Drop 대상) : ondatadragover + ondatadrop
    let eList1 = $c.gcm.createEList(["ondatadragstart"], "target1");
    let eList2 = $c.gcm.createEList(["ondatadragover", "ondatadrop"], "target2");

    // dataList 2개 생성 (각 그리드 바인딩)
    $c.gcm.createBasicDataList('', '', 'dlt_bind1');
    $c.gcm.createBasicDataList('', '', 'dlt_bind2');

    // target 2개 생성 (target1 : Drag 소스 = 왼쪽 / target2 : Drop 대상 = 오른쪽)
    //  - cParent 로 좌/우 셀(원시 DOM div)을 전달 -> getTestGroup 이 그대로 반환하여 해당 셀에 생성
    await $c.gcm.createBasicGridView(cList1, eList1, 'target1', cellLeft);
    await $c.gcm.createBasicGridView(cList2, eList2, 'target2', cellRight);
}



// ondatadragstart : Drag 시작 그리드(target1)에서 발생 -> 발생 순서 체인의 첫 단계
//  - ondatadragover 출력 카운터 초기화 (새 Drag 마다 다시 3회 출력)
scwin.target1_ondatadragstart = function (rowIndex) {
    scwin.overCnt = 0;
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ ondatadragstart (rowIndex=" + rowIndex + ")");
};



// ondatadragover : Drag 데이터가 다른 그리드(target2) 영역을 이동할 때 발생 -> 체인의 두번째 단계
//  - Drag-over 동안 연속 발생 -> 3회까지만 출력 (이후 생략)
scwin.target2_ondatadragover = function (fromId, fromRowIndex) {
    var bottom = wf_body_bottom.getObj("scwin");
    if (scwin.overCnt < 3) {
        bottom.setReturnValue("▶ ondatadragover (fromId=" + fromId + ", fromRowIndex=" + fromRowIndex + ")");
        if (scwin.overCnt === 2) {
            bottom.setReturnValue("... (이후 ondatadragover 출력 생략)");
        }
    }
    scwin.overCnt += 1;
};



// dragStartFunction : Drag 가 시작된 그리드(target1)에 정의된 사용자 함수 -> Drop 될 때 호출 (ondatadrop 보다 먼저)
//  - 기본(비-drilldown) 시그니처 : function(rowIndex, rowXml, infoObj)
scwin.target1_dragStartFunc = function (rowIndex, rowXml, infoObj) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ dragStartFunction 호출 (rowIndex=" + rowIndex + ")");
};



// ondatadrop : Drag 된 데이터가 다른 그리드(target2)에 Drop 되었을때 발생 -> 체인의 마지막 단계
//  - info 객체 1개 인자 (info.fromId / info.fromRowIndex / info.toRowIndex)
scwin.target2_ondatadrop = function (info) {
    var bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("▶ ondatadrop (info.fromId=" + info.fromId + ", info.fromRowIndex=" + info.fromRowIndex + ", info.toRowIndex=" + info.toRowIndex + ")");
};
